<?php
namespace App\Controllers\Admin;
use App\Controllers\BaseController; use App\Models\CategoryModel;
class Categories extends BaseController { public function index(){return view('admin/categories/index',['title'=>'Categories','rows'=>(new CategoryModel())->findAll()]);} public function new(){return view('admin/categories/form',['title'=>'New category']);} public function create(){if(!$this->validate(['name'=>'required|max_length[100]']))return redirect()->back()->withInput()->with('error','Name is required.');(new CategoryModel())->insert(['name'=>$this->request->getPost('name'),'slug'=>url_title($this->request->getPost('name'),'-',true)]);return redirect()->to('/admin/categories');} public function edit($id){return view('admin/categories/form',['title'=>'Edit category','row'=>(new CategoryModel())->find($id)]);} public function update($id){(new CategoryModel())->update($id,['name'=>$this->request->getPost('name'),'slug'=>url_title($this->request->getPost('name'),'-',true)]);return redirect()->to('/admin/categories');} public function delete($id){(new CategoryModel())->delete($id);return redirect()->to('/admin/categories');}}
